import java.util.*;
class OutOfStockException extends Exception { final int shortfall; OutOfStockException(String m,int s){super(m);shortfall=s;} }
class InvalidQuantityException extends Exception { InvalidQuantityException(String m){super(m);} }
class Warehouse { String[] items={"Mobile","Laptop","IdeaPad","Tablet"};int[] stock={45,25,35,18};void issue(String item,int qty)throws Exception{if(qty<=0)throw new InvalidQuantityException("Quantity must be greater than zero");int i=-1;for(int j=0;j<items.length;j++)if(items[j].equalsIgnoreCase(item)){i=j;break;}if(i<0)throw new Exception("Item not found");if(qty>stock[i])throw new OutOfStockException("Shortfall = "+(qty-stock[i]),qty-stock[i]);stock[i]-=qty;System.out.println(qty+" "+items[i]+" issued");}void show(){for(int i=0;i<items.length;i++)System.out.println(items[i]+": "+stock[i]);}}
public class Main { public static void main(String[] args){Scanner sc=new Scanner(System.in);Warehouse w=new Warehouse();System.out.print("Number of requests: ");int n=Integer.parseInt(sc.nextLine());for(int i=0;i<n;i++){System.out.print("Item: ");String item=sc.nextLine();System.out.print("Quantity: ");int qty=Integer.parseInt(sc.nextLine());try{w.issue(item,qty);}catch(Exception e){System.out.println("Issue failed: "+e.getMessage());}}System.out.println("Remaining stock:");w.show();sc.close();} }
